/**
 * Design system tokens and full workspace / dock stylesheets for Anime.js V4 Studio.
 */
export const STUDIO_STYLES: "\n:host {\n  all: initial;\n  --font-ui: Inter, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", monospace;\n\n  --bg-app: #0D0E10;\n  --bg-canvas: #090A0C;\n  --bg-panel: #141619;\n  --bg-elevated: #1B1E23;\n  --bg-control: #22262C;\n  --bg-control-hover: #2A2F37;\n  --bg-selected: rgba(74, 158, 255, 0.14);\n\n  --border-subtle: #23272E;\n  --border-strong: #313640;\n  --border-focus: #4A9EFF;\n\n  --text-primary: #ECEEF2;\n  --text-secondary: #9CA3AF;\n  --text-muted: #6B7280;\n\n  --accent: #4A9EFF;\n  --accent-hover: #63ACFF;\n  --playhead: #E5534B;\n  --success: #3FB950;\n  --warning: #D29922;\n  --purple: #A371F7;\n\n  --control-h: 24px;\n  --header-h: 38px;\n  --toolbar-h: 32px;\n\n  font-family: var(--font-ui);\n  font-size: 11px;\n  line-height: 1.35;\n  color: var(--text-primary);\n  -webkit-font-smoothing: antialiased;\n}\n\n:host([mode=\"dock\"]) {\n  position: fixed;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 2147483640;\n  pointer-events: none;\n}\n\n:host([mode=\"workspace\"]) {\n  position: fixed;\n  inset: 0;\n  width: 100vw;\n  height: 100vh;\n  z-index: 2147483640;\n  display: block;\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n}\n\n/* Custom slim technical scrollbars */\n::-webkit-scrollbar { width: 6px; height: 6px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb { background: #2B3038; border-radius: 3px; }\n::-webkit-scrollbar-thumb:hover { background: #3D4450; }\n\n/* Base Controls */\nbutton, select, input {\n  font-family: inherit;\n  font-size: 11px;\n  color: var(--text-primary);\n}\n\nbutton {\n  height: var(--control-h);\n  padding: 0 8px;\n  background: var(--bg-control);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: background-color 0.1s ease, border-color 0.1s ease, color 0.1s ease;\n}\nbutton:hover:not(:disabled) {\n  background: var(--bg-control-hover);\n  border-color: var(--border-strong);\n}\nbutton:focus-visible, select:focus-visible, input:focus-visible {\n  outline: none;\n  border-color: var(--border-focus);\n  box-shadow: 0 0 0 1px rgba(74, 158, 255, 0.35);\n}\nbutton:disabled {\n  opacity: 0.38;\n  cursor: not-allowed;\n}\nbutton.icon-btn {\n  width: var(--control-h);\n  padding: 0;\n}\nbutton.ghost {\n  background: transparent;\n  border-color: transparent;\n  color: var(--text-secondary);\n}\nbutton.ghost:hover:not(:disabled) {\n  background: var(--bg-control);\n  color: var(--text-primary);\n}\nbutton.active {\n  background: var(--bg-selected);\n  border-color: rgba(74, 158, 255, 0.55);\n  color: var(--accent);\n}\nbutton.primary {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: #090A0C;\n  font-weight: 600;\n}\nbutton.primary:hover:not(:disabled) {\n  background: var(--accent-hover);\n  border-color: var(--accent-hover);\n}\nbutton.success {\n  background: #238636;\n  border-color: #2EA043;\n  color: #F6F8FA;\n  font-weight: 600;\n}\nbutton.success:hover:not(:disabled) {\n  background: #2EA043;\n}\n\nselect, input[type=\"number\"], input[type=\"text\"] {\n  height: var(--control-h);\n  padding: 0 6px;\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  outline: none;\n  min-width: 0;\n}\ninput[type=\"number\"] {\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n}\ninput[type=\"range\"] {\n  accent-color: var(--accent);\n  cursor: pointer;\n}\nselect:hover:not(:disabled), input:hover:not(:disabled):not([readonly]) {\n  border-color: var(--border-strong);\n}\ninput[readonly] {\n  color: var(--text-secondary);\n  background: var(--bg-panel);\n}\n\n/* Target Highlighter Overlay */\n.overlay-layer {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  z-index: 2;\n}\n.highlight-box {\n  position: fixed;\n  border: 1px solid var(--accent);\n  background: rgba(74, 158, 255, 0.06);\n  pointer-events: none;\n}\n.highlight-tag {\n  position: absolute;\n  top: -17px;\n  left: -1px;\n  background: var(--accent);\n  color: #090A0C;\n  font-family: var(--font-mono);\n  font-size: 9px;\n  font-weight: 600;\n  padding: 1px 4px;\n  border-radius: 2px;\n  white-space: nowrap;\n}\n\n/* =========================================================\n   DESKTOP WORKSPACE SHELL (CSS GRID)\n   ========================================================= */\n.shell-workspace {\n  width: 100vw;\n  height: 100vh;\n  background: var(--bg-app);\n  display: grid;\n  grid-template-rows: var(--header-h) minmax(240px, 1fr) 4px var(--timeline-h, 256px);\n  grid-template-columns: var(--left-w, 240px) 4px minmax(340px, 1fr) 4px var(--right-w, 304px);\n  grid-template-areas:\n    \"header   header    header    header    header\"\n    \"left     split-l   canvas    split-r   right\"\n    \"split-t  split-t   split-t   split-t   split-t\"\n    \"timeline timeline  timeline  timeline  timeline\";\n  overflow: hidden;\n  user-select: none;\n}\n\n.shell-dock {\n  pointer-events: auto;\n  position: relative;\n  z-index: 3;\n  width: 100%;\n  background: var(--bg-panel);\n  border-top: 1px solid var(--border-strong);\n  display: flex;\n  flex-direction: column;\n  user-select: none;\n}\n.shell-dock.collapsed .dock-grid { display: none; }\n.shell-dock.collapsed .splitter-h { display: none; }\n\n.dock-grid {\n  display: grid;\n  grid-template-columns: var(--left-w, 200px) 1fr var(--right-w, 296px);\n  height: var(--timeline-h, 286px);\n  overflow: hidden;\n}\n\n/* Splitters */\n.splitter-v {\n  background: var(--bg-app);\n  border-left: 1px solid var(--border-subtle);\n  border-right: 1px solid var(--border-subtle);\n  cursor: ew-resize;\n  transition: background-color 0.12s;\n}\n.splitter-v:hover, .splitter-v.dragging { background: var(--accent); }\n\n.splitter-h {\n  height: 4px;\n  background: var(--bg-app);\n  border-top: 1px solid var(--border-subtle);\n  border-bottom: 1px solid var(--border-subtle);\n  cursor: ns-resize;\n  transition: background-color 0.12s;\n}\n.splitter-h:hover, .splitter-h.dragging { background: var(--accent); }\n\n/* A. APPLICATION HEADER */\n.app-header {\n  grid-area: header;\n  height: var(--header-h);\n  background: var(--bg-panel);\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0 10px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-width: 0;\n}\n\n.header-group {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n\n.brand-mark {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  font-weight: 600;\n  font-size: 12px;\n  letter-spacing: -0.01em;\n  color: var(--text-primary);\n  padding-right: 8px;\n  border-right: 1px solid var(--border-subtle);\n}\n.brand-version {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  color: var(--text-muted);\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  padding: 1px 4px;\n  border-radius: 2px;\n}\n\n.project-name-input {\n  width: 150px;\n  background: transparent;\n  border-color: transparent;\n  font-weight: 500;\n  color: var(--text-primary);\n  padding: 0 6px;\n}\n.project-name-input:hover { background: var(--bg-app); border-color: var(--border-subtle); }\n.project-name-input:focus { background: var(--bg-app); border-color: var(--border-focus); }\n\n.status-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 10px;\n  color: var(--text-secondary);\n  padding: 2px 7px;\n  border-radius: 3px;\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n}\n.status-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--success);\n}\n.status-dot.dirty { background: var(--warning); }\n\n.divider-v {\n  width: 1px;\n  height: 16px;\n  background: var(--border-subtle);\n  margin: 0 2px;\n}\n\n/* PANEL CHROME */\n.panel {\n  background: var(--bg-panel);\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n.panel-left { grid-area: left; }\n.panel-right { grid-area: right; }\n.panel-left.is-collapsed, .panel-right.is-collapsed { display: none; }\n\n.panel-header {\n  height: 28px;\n  flex-shrink: 0;\n  background: var(--bg-elevated);\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0 8px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 6px;\n}\n.panel-title {\n  font-size: 10px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: var(--text-secondary);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n/* B. LEFT SIDEBAR \u2014 LAYERS & OBJECTS */\n.layers-toolbar {\n  padding: 6px 8px;\n  border-bottom: 1px solid var(--border-subtle);\n  display: flex;\n  gap: 6px;\n  flex-shrink: 0;\n}\n.layers-search {\n  flex: 1;\n}\n\n.layers-tree {\n  flex: 1;\n  overflow-y: auto;\n  overflow-x: hidden;\n  padding: 4px 0;\n}\n\n.layer-row {\n  height: 26px;\n  padding: 0 6px 0 6px;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  cursor: pointer;\n  border-left: 2px solid transparent;\n  color: var(--text-secondary);\n}\n.layer-row:hover {\n  background: rgba(255, 255, 255, 0.03);\n  color: var(--text-primary);\n}\n.layer-row.selected {\n  background: var(--bg-selected);\n  border-left-color: var(--accent);\n  color: var(--text-primary);\n}\n.layer-row.sub {\n  height: 23px;\n  padding-left: 22px;\n  font-size: 10.5px;\n}\n.layer-row.is-hidden {\n  opacity: 0.45;\n}\n.layer-swatch {\n  width: 7px;\n  height: 7px;\n  border-radius: 1.5px;\n  flex-shrink: 0;\n}\n.layer-label {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.layer-count {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  color: var(--text-muted);\n  padding: 0 4px;\n}\n.layer-actions {\n  display: flex;\n  align-items: center;\n  gap: 1px;\n  opacity: 0.65;\n}\n.layer-row:hover .layer-actions,\n.layer-row.selected .layer-actions,\n.layer-actions.pinned {\n  opacity: 1;\n}\n.layer-act-btn {\n  width: 20px;\n  height: 20px;\n  padding: 0;\n  border: none;\n  background: transparent;\n  color: var(--text-muted);\n}\n.layer-act-btn:hover { background: var(--bg-control); color: var(--text-primary); }\n.layer-act-btn.on { color: var(--accent); }\n.layer-act-btn.warn { color: var(--warning); }\n\n/* C. CENTRAL WORKSPACE \u2014 CANVAS VIEWPORT */\n.canvas-workspace {\n  grid-area: canvas;\n  background: var(--bg-canvas);\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.canvas-subbar {\n  height: 28px;\n  flex-shrink: 0;\n  background: var(--bg-panel);\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0 10px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.canvas-stage-wrap {\n  flex: 1;\n  position: relative;\n  overflow: hidden;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n  background-color: var(--bg-canvas);\n}\n.canvas-stage-wrap.with-grid {\n  background-image:\n    linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),\n    linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);\n  background-size: 24px 24px;\n}\n.canvas-stage-wrap.pan-mode { cursor: grab; }\n.canvas-stage-wrap.pan-mode:active { cursor: grabbing; }\n\n.composition-viewport {\n  position: relative;\n  border: 1px solid var(--border-strong);\n  background: #111317;\n  transform-origin: center center;\n  flex-shrink: 0;\n}\n.composition-guides {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  z-index: 4;\n}\n.composition-guides::before {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 0;\n  bottom: 0;\n  width: 1px;\n  background: rgba(74, 158, 255, 0.2);\n}\n.composition-guides::after {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 0;\n  right: 0;\n  height: 1px;\n  background: rgba(74, 158, 255, 0.2);\n}\n\n.canvas-dims {\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--text-muted);\n}\n\n/* D. RIGHT SIDEBAR \u2014 PROPERTIES INSPECTOR */\n.inspector-scroll {\n  flex: 1;\n  overflow-y: auto;\n  overflow-x: hidden;\n}\n\n.inspector-context-bar {\n  padding: 8px 10px;\n  border-bottom: 1px solid var(--border-subtle);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  background: var(--bg-panel);\n}\n.context-title {\n  font-weight: 600;\n  color: var(--text-primary);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.context-type {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  text-transform: uppercase;\n  color: var(--accent);\n  background: var(--bg-selected);\n  padding: 2px 5px;\n  border-radius: 2px;\n  flex-shrink: 0;\n}\n\n.section {\n  border-bottom: 1px solid var(--border-subtle);\n}\n.section-head {\n  height: 28px;\n  padding: 0 10px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  cursor: pointer;\n  background: var(--bg-panel);\n  color: var(--text-secondary);\n  font-size: 10px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n.section-head:hover { background: var(--bg-elevated); color: var(--text-primary); }\n.section-head-left { display: flex; align-items: center; gap: 5px; }\n.section-body {\n  padding: 8px 10px 10px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  background: #121417;\n}\n.section.collapsed .section-body { display: none; }\n\n.prop-subgroup {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.prop-sublabel {\n  font-size: 10px;\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.prop-row {\n  display: grid;\n  grid-template-columns: 70px 1fr 1fr;\n  align-items: center;\n  gap: 5px;\n}\n.prop-row-2 {\n  display: grid;\n  grid-template-columns: 78px 1fr;\n  align-items: center;\n  gap: 6px;\n}\n.prop-name {\n  font-size: 10.5px;\n  color: var(--text-secondary);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.prop-field-wrap {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  min-width: 0;\n}\n.prop-mini-tag {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  color: var(--text-muted);\n  width: 14px;\n  flex-shrink: 0;\n}\n.prop-field-wrap input {\n  width: 100%;\n}\n\n.grid-2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 6px;\n}\n.grid-3 {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 6px;\n}\n.field-col {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  min-width: 0;\n}\n.field-col label {\n  font-size: 9.5px;\n  color: var(--text-muted);\n}\n\n/* Easing & Curve Graph */\n.preset-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 4px;\n}\n.preset-grid button {\n  height: 22px;\n  font-size: 10px;\n  padding: 0 4px;\n}\n\n.curve-panel {\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  padding: 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.curve-svg {\n  width: 100%;\n  max-width: 172px;\n  height: 122px;\n  align-self: center;\n  overflow: visible;\n  touch-action: none;\n}\n.bezier-handle { cursor: grab; }\n.bezier-handle:active { cursor: grabbing; }\n\n.slider-line {\n  display: grid;\n  grid-template-columns: 58px 1fr 40px;\n  align-items: center;\n  gap: 6px;\n  font-size: 10px;\n}\n.slider-line span:first-child { color: var(--text-secondary); }\n.slider-line span:last-child {\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  color: var(--text-primary);\n}\n\n/* Stagger Waterfall inside Inspector */\n.stagger-list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  max-height: 150px;\n  overflow-y: auto;\n}\n.stagger-row {\n  display: grid;\n  grid-template-columns: 72px 1fr 44px;\n  align-items: center;\n  gap: 6px;\n  font-size: 10px;\n}\n.stagger-bar-bg {\n  height: 8px;\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 2px;\n  position: relative;\n  overflow: hidden;\n}\n.stagger-bar-fill {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n}\n\n/* E. BOTTOM WORKSPACE \u2014 TIMELINE */\n.timeline-workspace {\n  grid-area: timeline;\n  background: var(--bg-panel);\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.playback-toolbar {\n  height: var(--toolbar-h);\n  flex-shrink: 0;\n  background: var(--bg-elevated);\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0 10px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.timecode-display {\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n  font-size: 11px;\n  color: var(--text-primary);\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  padding: 0 8px;\n  height: var(--control-h);\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.timecode-sub { color: var(--text-muted); font-size: 10px; }\n\n.timeline-split {\n  flex: 1;\n  display: grid;\n  grid-template-columns: var(--tl-tree-w, 240px) 1fr;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.tl-tree-pane {\n  display: flex;\n  flex-direction: column;\n  border-right: 1px solid var(--border-strong);\n  background: var(--bg-panel);\n  min-width: 0;\n  min-height: 0;\n}\n.tl-tree-head {\n  height: 30px;\n  flex-shrink: 0;\n  padding: 0 8px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 9.5px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: var(--text-muted);\n  border-bottom: 1px solid var(--border-subtle);\n  background: var(--bg-panel);\n}\n.tl-tree-body {\n  flex: 1;\n  overflow-y: auto;\n  overflow-x: hidden;\n}\n\n.tl-track-row {\n  height: var(--track-row-h, 28px);\n  padding: 0 8px;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  border-bottom: 1px solid var(--border-subtle);\n  cursor: pointer;\n  color: var(--text-secondary);\n}\n.tl-track-row:hover { background: rgba(255, 255, 255, 0.025); color: var(--text-primary); }\n.tl-track-row.selected { background: var(--bg-selected); color: var(--text-primary); }\n.tl-track-row.sub {\n  height: var(--track-sub-h, 23px);\n  padding-left: 24px;\n  background: #111316;\n  font-size: 10px;\n}\n.tl-track-row.sub.selected { background: var(--bg-selected); }\n.tl-track-row.is-locked { color: var(--text-muted); }\n\n.tl-lanes-pane {\n  flex: 1;\n  overflow: auto;\n  position: relative;\n  background: #0F1114;\n  min-width: 0;\n  min-height: 0;\n}\n\n.tl-canvas-inner {\n  position: relative;\n  min-width: 100%;\n  min-height: 100%;\n}\n\n.tl-tracks-inset {\n  position: relative;\n  margin: 0 12px;\n  min-height: 100%;\n}\n\n.ruler-track {\n  position: sticky;\n  top: 0;\n  z-index: 6;\n  height: 30px;\n  margin: 0 -12px;\n  padding: 0 12px;\n  background: var(--bg-elevated);\n  border-bottom: 1px solid var(--border-strong);\n  cursor: ew-resize;\n}\n\n.ruler-coords {\n  position: relative;\n  height: 100%;\n}\n\n.ruler-tick {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  border-left: 1px solid #2A2F38;\n  font-family: var(--font-mono);\n  font-size: 9px;\n  line-height: 10px;\n  color: var(--text-muted);\n  padding: 2px 0 0 4px;\n  pointer-events: none;\n}\n.ruler-tick.minor {\n  top: 21px;\n  border-left-color: #21252C;\n}\n\n.ruler-label {\n  position: absolute;\n  bottom: 2px;\n  transform: translateX(-50%);\n  background: #6E40C9;\n  color: #F6F8FA;\n  font-family: var(--font-mono);\n  font-size: 8.5px;\n  line-height: 12px;\n  padding: 0 4px;\n  border-radius: 2px;\n  pointer-events: none;\n  white-space: nowrap;\n}\n\n.ruler-call {\n  position: absolute;\n  bottom: 3px;\n  width: 6px;\n  height: 6px;\n  transform: translateX(-50%) rotate(45deg);\n  background: var(--warning);\n  pointer-events: none;\n}\n\n.playhead-line {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  width: 1px;\n  background: var(--playhead);\n  z-index: 8;\n  pointer-events: none;\n}\n.playhead-head {\n  position: sticky;\n  top: 0;\n  margin-left: -5px;\n  width: 11px;\n  height: 12px;\n  background: var(--playhead);\n  clip-path: polygon(0 0, 100% 0, 100% 55%, 50% 100%, 0 55%);\n}\n\n.tl-lane-row {\n  height: var(--track-row-h, 28px);\n  position: relative;\n  border-bottom: 1px solid var(--border-subtle);\n}\n.tl-lane-row.sub {\n  height: var(--track-sub-h, 23px);\n  background: rgba(255, 255, 255, 0.01);\n}\n.tl-lane-row.selected {\n  background: rgba(74, 158, 255, 0.04);\n}\n\n.bar-wrap {\n  position: absolute;\n  top: 3px;\n  bottom: 3px;\n  display: flex;\n  align-items: stretch;\n  cursor: grab;\n}\n.bar-wrap:active { cursor: grabbing; }\n.bar-wrap.locked { cursor: not-allowed; opacity: 0.65; }\n\n.bar-delay {\n  background: repeating-linear-gradient(\n    -45deg,\n    rgba(255, 255, 255, 0.08),\n    rgba(255, 255, 255, 0.08) 3px,\n    transparent 3px,\n    transparent 6px\n  );\n  border: 1px dashed rgba(255, 255, 255, 0.22);\n  border-right: none;\n  border-radius: 2px 0 0 2px;\n}\n\n.bar-body {\n  position: relative;\n  flex: 1;\n  min-width: 6px;\n  border-radius: 2px;\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  display: flex;\n  align-items: center;\n  overflow: hidden;\n}\n.bar-wrap.selected .bar-body {\n  border-color: #FFFFFF;\n  box-shadow: 0 0 0 1px #FFFFFF;\n}\n\n.bar-spark {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  opacity: 0.35;\n  pointer-events: none;\n}\n\n.bar-text {\n  position: relative;\n  z-index: 1;\n  font-family: var(--font-mono);\n  font-size: 9.5px;\n  font-weight: 600;\n  color: #0D0E10;\n  padding: 0 6px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.bar-resize {\n  position: absolute;\n  right: 0;\n  top: 0;\n  bottom: 0;\n  width: 6px;\n  cursor: ew-resize;\n  background: rgba(0, 0, 0, 0.22);\n}\n.bar-resize:hover { background: #FFFFFF; }\n\n.kf-diamond {\n  position: absolute;\n  top: 50%;\n  width: 7px;\n  height: 7px;\n  background: #ECEEF2;\n  border: 1px solid #0D0E10;\n  transform: translate(-50%, -50%) rotate(45deg);\n  z-index: 3;\n  pointer-events: none;\n}\n.kf-diamond.active { background: #F0B72F; }\n\n/* EXPORT MODAL */\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.68);\n  z-index: 20;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n.modal-dialog {\n  width: 560px;\n  max-width: 96vw;\n  max-height: 86vh;\n  background: var(--bg-panel);\n  border: 1px solid var(--border-strong);\n  border-radius: 4px;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n.modal-header {\n  height: 36px;\n  padding: 0 12px;\n  background: var(--bg-elevated);\n  border-bottom: 1px solid var(--border-subtle);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-weight: 600;\n}\n.modal-tabs {\n  display: flex;\n  border-bottom: 1px solid var(--border-subtle);\n  background: var(--bg-panel);\n  padding: 0 10px;\n  gap: 4px;\n}\n.modal-tab {\n  height: 30px;\n  background: transparent;\n  border: none;\n  border-bottom: 2px solid transparent;\n  border-radius: 0;\n  color: var(--text-secondary);\n  padding: 0 10px;\n}\n.modal-tab.active {\n  color: var(--text-primary);\n  border-bottom-color: var(--accent);\n}\n.modal-body {\n  padding: 12px;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.filmstrip {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 6px;\n}\n.film-thumb {\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  overflow: hidden;\n  cursor: pointer;\n  display: flex;\n  flex-direction: column;\n}\n.film-thumb:hover { border-color: var(--accent); }\n.film-thumb img { width: 100%; aspect-ratio: 16/9; object-fit: contain; display: block; background: #090A0C; }\n.film-thumb span {\n  font-family: var(--font-mono);\n  font-size: 9px;\n  padding: 3px 4px;\n  color: var(--text-secondary);\n  text-align: center;\n}\n\n.code-block {\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 3px;\n  padding: 10px;\n  margin: 0;\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  line-height: 1.45;\n  color: #D2E0FF;\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 280px;\n  overflow: auto;\n  user-select: text;\n}\n\n.status-banner {\n  padding: 6px 8px;\n  border-radius: 3px;\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  color: var(--accent);\n}\n\n.empty-state {\n  padding: 24px 14px;\n  text-align: center;\n  color: var(--text-muted);\n  font-size: 11px;\n}\n\n/* Dock Mode compact header adjustments */\n.dock-header {\n  height: 32px;\n  background: var(--bg-elevated);\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0 8px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n";
